 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 4
    # Complete separator rows/columns divide the canvas into repeated panels.
    divider_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    divider_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    row_ranges = []
    start = 0
    for r in divider_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in divider_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    # Background is the most frequent non-divider color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != sep)
    bg = counts.most_common(1)[0][0]
    panels = []
    for ra, rb in row_ranges:
        for ca, cb in col_ranges:
            content = sum(grid[r][c] != bg for r in range(ra, rb) for c in range(ca, cb))
            panels.append((content, ra, rb, ca, cb))
    _, sr, er, sc, ec = max(panels)
    template = [row[sc:ec] for row in grid[sr:er]]
    out = [row[:] for row in grid]
    for _, ra, rb, ca, cb in panels:
        if rb - ra == len(template) and cb - ca == len(template[0]):
            for i in range(rb - ra):
                for j in range(cb - ca):
                    out[ra + i][ca + j] = template[i][j]
    return out
